const D = { energy:.6, density:.5, hue:210, speed:1, scale:1, chop:.5, spray:.5, lightning:.5, x:.5, y:.42, seed:0, style:'dark marine', act:'squall' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const W = width, H = height, u = Math.min(W,H), TAU = Math.PI*2;
const hue = ((P.hue%360)+360)%360;
const st = P.style;
const wind = P.x - .5, windSign = wind >= 0 ? 1 : -1, windMag = .5 + Math.abs(wind);
const horizon = H * P.y;

// smoothed audio (blended ON TOP of clk baseline, never as sole motion)
S.bass = (S.bass||0)*.85 + (A.bass||0)*.15;
S.tre  = (S.tre ||0)*.7  + (A.treble||0)*.3;
S.rms  = (S.rms ||0)*.85 + (A.rms||0)*.15;

// dramaturgy: act + section arc -> storm scalar (30s..5min evolution via K.section/intensity)
const sec = (K.intensity != null ? K.intensity : .6);
const act = P.act;
const stormBase = act==='doldrums' ? .30 : act==='swell' ? .62 : .48;
const stormArc  = act==='squall'   ? sec : act==='swell' ? (.55 + .45*sec) : (.15 + .85*sec);
const storm = Math.min(1.5, (stormBase*.5 + stormArc) * (0.55 + 0.9*P.energy) + S.rms*.4);

// continuous real-time drift (NEVER re-phases at 8s — the motion floor)
const drift = K.t * P.speed * windSign;
const ampScale = P.scale * (0.7 + 1.2*storm);
const nB = Math.max(3, Math.round(3 + 5*P.density));

// per-style spray tint
let sprH = hue, sprS = 10;
if (st==='ink wash'){ sprS = 0; }
else if (st==='blueprint'){ sprH = 190; sprS = 60; }
else if (st==='thermal'){ sprH = 50; sprS = 40; }
else if (st==='riso'){ sprH = 8; sprS = 70; }

const heat = (v) => { const stops=[[235,80,30],[270,78,45],[330,82,58],[355,85,68],[380,90,80],[412,95,90]];
  v=Math.max(0,Math.min(.999,v)); const f=v*(stops.length-1), i=Math.floor(f), g2=f-i, a=stops[i], b=stops[i+1];
  return [(a[0]+(b[0]-a[0])*g2)%360, a[1]+(b[1]-a[1])*g2, a[2]+(b[2]-a[2])*g2]; };

// ---- cached backdrop (sky gradient + style texture), keyed on size/seed/style/hue/horizon ----
const bkey = W+'x'+H+':'+P.seed+':'+st+':'+Math.round(hue)+':'+Math.round(P.y*100);
if (!S.base || S.bkey !== bkey){
  const g = createGraphics(W,H); g.colorMode(HSB,360,100,100,100); g.noStroke();
  if (st==='ink wash'){
    for (let y=0;y<horizon;y+=2){ const f=y/horizon; g.fill(0,0, 58+26*f); g.rect(0,y,W,2); }
    g.fill(0,0,20); g.rect(0,horizon,W,H-horizon);
  } else if (st==='blueprint'){
    g.fill(220,62,13); g.rect(0,0,W,H);
    g.stroke(190,55,55,9); g.strokeWeight(1); const gs=u*0.075;
    for (let x=0;x<=W;x+=gs) g.line(x,0,x,H);
    for (let y=0;y<=H;y+=gs) g.line(0,y,W,y);
    g.noStroke();
  } else if (st==='thermal'){
    for (let y=0;y<horizon;y+=2){ const f=y/horizon; g.fill(235, 72, 9+16*f); g.rect(0,y,W,2); }
    g.fill(232,70,14); g.rect(0,horizon,W,H-horizon);
  } else if (st==='riso'){
    g.fill(42,11,88); g.rect(0,0,W,H);
    g.fill(210,18,64,16); const ds=u*0.028;
    for (let y=0;y<H;y+=ds) for (let x=(Math.floor(y/ds)%2?ds/2:0);x<W;x+=ds) g.circle(x,y,ds*0.34);
  } else { // dark marine (anchor)
    for (let y=0;y<horizon;y+=2){ const f=y/horizon; const gl=Math.pow(f,1.6);
      g.fill((hue+ (12-24*f))%360, 30-16*f, 20+24*gl + 8*Math.sin(f*3.1)); g.rect(0,y,W,2); }
    // ominous horizon glow
    g.fill((hue+20)%360, 24, 50, 40); g.rect(0,horizon-u*0.06,W,u*0.12);
    g.fill(hue, 40, 11); g.rect(0,horizon,W,H-horizon);
  }
  S.base = g; S.bkey = bkey;
}
image(S.base,0,0);

// ---- cloud churn (drifts on K.t; motion even without waves) ----
noStroke();
const nC = Math.max(3, Math.round(3 + 3*P.density));
for (let i=0;i<nC;i++){
  const cw = u*(0.42+0.55*fr(i*3+2))*(1+0.35*storm);
  const cy = horizon*(0.18+0.6*fr(i*3+1)) - u*0.02;
  const ch = cw*(0.24+0.14*fr(i*3+3));
  const span = W + cw;
  let cx = ((fr(i*3)*span + drift*(7+i*2)) % span + span) % span - cw/2;
  if (st==='blueprint'){
    noFill(); stroke(190,65,60,26); strokeWeight(1);
    ellipse(cx,cy,cw,ch); ellipse(cx,cy,cw*0.7,ch*0.7); noStroke();
  } else if (st==='riso'){
    blendMode(MULTIPLY);
    fill(175,55,70,16); ellipse(cx-u*0.008,cy,cw,ch);
    fill(8,62,80,13); ellipse(cx+u*0.01,cy+u*0.006,cw*0.94,ch);
    blendMode(BLEND);
  } else {
    const dk = st==='ink wash', th = st==='thermal';
    const ch1 = dk?[0,0,34]:th?[232,60,20]:[(hue+8)%360,18,13];
    for (let l=0;l<3;l++){ const s=1-l*0.24;
      fill(ch1[0],ch1[1],ch1[2], (dk?11:9)+l*6); ellipse(cx,cy,cw*s,ch*s); }
  }
}

// ---- lightning: baseline schedule (audio-independent) + treble trigger; partial-frame ----
if (S.nextBolt==null || S.nextBolt>K.t+40 || S.nextBolt<K.t-2) S.nextBolt = K.t + (1.4+3*fr(7));
const boltRate = 0.3 + P.lightning*1.5 + storm*0.6;
if (K.t >= S.nextBolt){
  S.flash = Math.min(1, 0.65+0.5*P.lightning);
  S.boltX = fr(Math.floor(K.t*11)+3)*W;
  S.boltJ = Math.floor(K.t*11);
  S.nextBolt = K.t + (0.6 + 2.6*fr(Math.floor(K.t*7)+5)) / Math.max(0.25, boltRate);
}
if (S.tre>0.45 && S.tre>(S.treP||0)+0.06 && P.lightning>0){
  S.flash = Math.min(1, 0.7+0.5*P.lightning); S.boltX = fr(Math.floor(K.t*13)+9)*W; S.boltJ = Math.floor(K.t*13);
}
S.treP = S.tre;
if (S.flash>0.02){
  const fa = S.flash*(18 + 26*P.lightning);
  const fh = st==='blueprint'?190 : st==='thermal'?52 : st==='riso'?45 : (hue+6)%360;
  blendMode(SCREEN); noStroke();
  fill(fh, st==='ink wash'?0:14, 94, fa);
  rect(0,0,W, horizon);                 // top region ONLY -> strobe-safe partial frame
  // jagged bolt
  blendMode(st==='riso'?BLEND:ADD);
  stroke(fh, st==='ink wash'?0:20, 96, S.flash*80); strokeWeight(1.6+P.lightning*1.4);
  let bx=S.boltX, by=0; const segs=7;
  for (let s2=1;s2<=segs;s2++){ const ny=horizon*s2/segs; const nx=bx + (fr(S.boltJ*3+s2)-.5)*u*0.09; line(bx,by,nx,ny); bx=nx; by=ny; }
  noStroke(); blendMode(BLEND);
  S.flash *= 0.80;
} else S.flash = 0;

// ---- sea: heaving swell bands, drawn far -> near ----
if (st==='blueprint') noFill();
const step = Math.max(8, W/90);
for (let bi=0;bi<nB;bi++){
  const t = nB>1 ? bi/(nB-1) : 1;
  const yBase = horizon + (H-horizon)*Math.pow(t,1.35);
  const amp = u*(0.006+0.05*t)*ampScale;
  const wl  = u*(0.5+1.9*t)/(0.55+P.scale*0.6);
  const ph  = drift*(0.6+t*1.1) + bi*1.7;
  const heave = Math.sin(K.beat*0.5*P.speed + bi)*u*0.010*storm + K.swell*u*0.008*storm;
  const crest = (x) => { const nx=x/wl;
    return yBase + heave
      - amp*Math.sin(nx*TAU + ph)
      - amp*0.5*Math.sin(nx*TAU*2.3 + ph*1.7 + bi)
      - amp*P.chop*0.75*Math.sin(nx*TAU*5.1 + drift*2.2 + bi*2); };

  if (st==='blueprint'){
    stroke(190,68, 78-38*t, 68-34*t); strokeWeight(1); noFill();
    beginShape(); for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x)); endShape();
  } else if (st==='riso'){
    const off = u*0.011*(0.5+storm);
    blendMode(MULTIPLY); noStroke();
    fill(175, 62, 66, 42); beginShape();
      for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x));
      vertex(W+step,H); vertex(-step,H); endShape(CLOSE);
    fill(8, 68, 80, 34); beginShape();
      for (let x=-step;x<=W+step;x+=step) vertex(x+off,crest(x)+off);
      vertex(W+step,H); vertex(-step,H); endShape(CLOSE);
    blendMode(BLEND);
  } else if (st==='thermal'){
    const hc = heat(0.15+0.8*t); noStroke();
    fill(hc[0],hc[1],hc[2]); beginShape();
      for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x));
      vertex(W+step,H); vertex(-step,H); endShape(CLOSE);
    const sh = heat(Math.min(0.99,0.35+0.8*t));
    stroke(sh[0], sh[1]*0.7, Math.min(96,sh[2]+16), 70); strokeWeight(1.4); noFill();
    beginShape(); for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x)); endShape();
  } else if (st==='ink wash'){
    noStroke(); fill(0,0, 28-14*t, 44); beginShape();
      for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x));
      vertex(W+step,H); vertex(-step,H); endShape(CLOSE);
  } else { // dark marine
    noStroke(); fill(hue, 22+30*t, 22-13*t); beginShape();
      for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x));
      vertex(W+step,H); vertex(-step,H); endShape(CLOSE);
    stroke((hue+14)%360, 26, 40+22*t, 46); strokeWeight(1.4); noFill();
    beginShape(); for (let x=-step;x<=W+step;x+=step) vertex(x,crest(x)); endShape();
    noStroke();
  }

  // foam / whitecaps on the near bands
  if (t>0.45 && st!=='blueprint'){
    const foamP = 0.10 + 0.55*P.energy + storm*0.15;
    const fw = st==='ink wash' ? [0,0,90] : st==='thermal' ? [55,40,96] : st==='riso' ? [8,60,72] : [(hue+10)%360,10,92];
    if (st==='riso') blendMode(MULTIPLY);
    stroke(fw[0],fw[1],fw[2], 78); strokeWeight(1.2+t);
    for (let x=0;x<=W;x+=step){ if (fr(bi*97 + x*0.13 + Math.floor(drift*3))<foamP){
      const y0=crest(x), y1=crest(x+step*0.7); stroke(fw[0],fw[1],fw[2], 55+40*Math.min(1,Math.abs(y0-y1)/(amp+1)));
      line(x, y0-1, x+step*0.6, y1-1); } }
    noStroke(); if (st==='riso') blendMode(BLEND);
  }
}

// ---- spray particles (continuous emission -> strong real-time motion floor) ----
if (S.lt==null || K.t<S.lt) S.lt = K.t;
let dt = Math.min(0.05, Math.max(0, K.t - S.lt)); S.lt = K.t;
S.sp = S.sp || []; S.si = S.si || 0;
const nearCrestY = horizon + (H-horizon)*Math.pow(0.82,1.35) - u*0.02;
const emit = Math.round((1.5 + 11*P.spray) * (0.3+storm) * (dt/0.016));
for (let k=0;k<emit && S.sp.length<130;k++){
  S.si++; const px = fr(S.si*1.7)*W;
  S.sp.push({ x:px, y:nearCrestY - u*0.01*fr(S.si),
    vx: windSign*(0.35+fr(px)*0.8)*windMag + (fr(px*2)-.5)*0.6,
    vy: -(1.1+2.1*fr(px*3))*(0.6+storm), l:1 });
}
noStroke();
for (const p of S.sp){ p.x += p.vx*u*0.02; p.y += p.vy*u*0.02; p.vy += u*0.0011; p.l -= dt*1.1; }
S.sp = S.sp.filter(p => p.l>0 && p.y<H+4);
for (const p of S.sp){ const a = p.l*70*(0.4+P.spray);
  fill(sprH, sprS, 92, a); circle(p.x, p.y, u*0.006*(0.4+p.l)); }

blendMode(BLEND);
drawingContext.shadowBlur = 0;
